{
  "arguments": "{\"action\":\"read\",\"snapshotId\":\"capture-630c1226-628b-4cfb-9aa8-02074d2f0ff6\",\"query\":\"per-interpreter GIL sub-interpreters C-API Py_NewInterpreterFromConfig\"}",
