  "arguments": "{\"action\":\"read\",\"snapshotId\":\"capture-bc09795d-ddf0-4e94-b4a3-fe2b7560bf21\",\"query\":\"per-interpreter GIL sub-interpreters unique GIL C-API Python API anticipated process-global resources shared no plans\"}",
