:14883,\"charEnd\":15186,\"text\":\"Some examples use the reflect-metadata library which adds a polyfill for an experimental metadata API. This library is not yet part of the ECMAScript (JavaScript) standard. However, once decorators are officially adopted as part of the ECMAScript standard these extensions will be proposed for adoption.\"},{\"charStart\":15227,\"charEnd\":15256,\"text\":\"npm i reflect-metadata --save\"},{\"charStart\":15258,\"charEnd\":15521,\"text\":\"TypeScript includes experimental support for emitting certain types of metadata for declarations that have decorators. To enable this experimental support, you must set the emitDecoratorMetadata compiler option either on the command line or in your tsconfig.json:\"},{\"charStart\":15538,\"charEnd\":15603,\"text\":\"tsc --target ES5 --experimentalDecorators --emitDecoratorMetadata\"},{\"charStart\":15621,\"charEnd\":15742,\"text\":\"{\\n  \\\"compilerOptions\\\": {\\n    \\\"target\\\": \\\"ES5\\\",\\n    \\\"experimentalDecorators\\\": true,\\n    \\\"emitDecoratorMetadata\\\": true\\n  }\\n}\"},{\"charStart\":15744,\"charEnd\":15884,\"text\":\"When enabled, as long as the reflect-metadata library has been imported, additional design-time type information will be exposed at runtime.\"},{\"charStart\":15939,\"charEnd\":16895,\"text\":\"import \\\"reflect-metadata\\\";\\n \\nclass Point {\\n  constructor(public x: number, public y: number) {}\\n}\\n \\nclass Line {\\n  private _start: Point;\\n  private _end: Point;\\n \\n  @validate\\n  set start(value: Point) {\\n    this._start = value;\\n  }\\n \\n  get start() {\\n    return this._start;\\n  }\\n \\n  @validate\\n  set end(value: Point) {\\n    this._end = value;\\n  }\\n \\n  get end() {\\n    return this._end;\\n  }\\n}\\n \\nfunction validate<T>(target: any, propertyKey: string, descriptor: TypedPropertyDescriptor<T>) {\\n  let set = descriptor.set!;\\n  \\n  descriptor.set = function (value: T) {\\n    let type = Reflect.getMetadata(\\\"design:type\\\", target, propertyKey);\\n \\n    if (!(value instanceof type)) {\\n      throw new TypeError(`Invalid type, got ${typeof value} not ${type.name}.`);\\n    }\\n \\n    set.call(this, value);\\n  };\\n}\\n \\nconst line = new Line()\\nline.start = new Point(0, 0)\\n \\n// @ts-ignore\\n// line.end = {}\\n \\n// Fails at runtime with:\\n// > Invalid type, got object not Point\\n \\nTry\"},{\"charStart\":16897,\"charEnd\":16927,\"text\":\"The TypeScript compiler will i\"}],\"sourcePath\":\"C:\\\\Temp\\\\weftmate-fact1-32453ca3-ce97-4ece-8ea1-120b2180dc3f\\\\profile\\\\conversations\\\\be02ee38d3982f0d63a1fde99286ad6e6c6bb84f1674ceced8222269cc953289\\\\session-0149d2c9-9df6-4860-8425-7047a0c41387\\\\.weftmate-web-sources\\\\capture-43a8bc5d-f4e2-4d02-bf19-fc8a1320c47a.txt\"}"
