n    return this._end;\\n  }\\n}\\n \\nfunction validate<T>(target: any, propertyKey: string, descriptor: TypedPropertyDescriptor<T>) {\\n  let set = descriptor.set!;\\n  \\n  descriptor.set = function (value: T) {\\n    let type = Reflect.getMetadata(\\\"design:type\\\", target, propertyKey);\n\n[... tool result middle pruned ...]\n\nype)) {\\n      throw new TypeError(`Invalid type, got ${typeof value} not ${type.name}.`);\\n    }\\n \\n    set.call(this, value);\\n  };\\n}\\n \\nconst line = new Line()\\nline.start = new Point(0, 0)\\n \\n// @ts-ignore\\n// line.end = {}\\n \\n// Fails at runtime with:\\n// > Invalid type, got object not Point\\n \\nTry\"},{\"charStart\":17068,\"charEnd\":17425,\"text\":\"class Line {\\n  private _start: Point;\\n  private _end: Point;\\n  @validate\\n  @Reflect.metadata(\\\"design:type\\\", Point)\\n  set start(value: Point) {\\n    this._start = value;\\n  }\\n  get start() {\\n    return this._start;\\n  }\\n  @validate\\n  @Reflect.metadata(\\\"design:type\\\", Point)\\n  set end(value: Point) {\\n    this._end = value;\\n  }\\n  get end() {\\n    return this._end\"}],\"sourcePath\":\"C:\\\\Temp\\\\weftmate-fact1-32453ca3-ce97-4ece-8ea1-120b2180dc3f\\\\profile\\\\conversations\\\\be02ee38d3982f0d63a1fde99286ad6e6c6bb84f1674ceced8222269cc953289\\\\session-0149d2c9-9df6-4860-8425-7047a0c41387\\\\.weftmate-web-sources\\\\capture-43a8bc5d-f4e2-4d02-bf19-fc8a1320c47a.txt\"}"
