: ClassMethodDecoratorContext) {\\n    const methodName = String(context.name);\\n    function replacementMethod(this: any, ...args: any[]) {\\n        console.log(`LOG: Entering method '${methodName}'.`)\\n        const result = originalMethod.call(this, ...args);\\n        console.log(`LOG: Exiting method '${methodName}'.`)\\n        return result;\\n    }\\n    return \"}],\"sourcePath\":\"C:\\\\Temp\\\\weftmate-fact1-32453ca3-ce97-4ece-8ea1-120b2180dc3f\\\\profile\\\\conversations\\\\be02ee38d3982f0d63a1fde99286ad6e6c6bb84f1674ceced8222269cc953289\\\\session-0149d2c9-9df6-4860-8425-7047a0c41387\\\\.weftmate-web-sources\\\\capture-c75e7572-2375-4a13-8fc8-cb92d511133f.txt\"}"
